    <script>
        (() => { const form=document.querySelector('[data-invoice-design-form]'), cards=[...document.querySelectorAll('[data-template-card]')], preview=document.querySelector('[data-invoice-design-preview]'), count=document.querySelector('[data-template-count]'), orientation=document.querySelector('[data-orientation-control]'), taxFilter=document.querySelector('[data-template-filter="tax"]'), gstFilter=document.querySelector('[data-template-filter="gst"]'), styleFilter=document.querySelector('[data-template-filter="style"]'); const formats={!! json_encode($templates) !!}; const selectedFormat=()=>form.querySelector('input[name="paper_format"]:checked')?.value; const selectedTemplate=()=>form.querySelector('input[name="template_key"]:checked')?.value; const refresh=()=>{const format=selectedFormat(), tax=taxFilter.value, gst=gstFilter.value, style=styleFilter.value; let visible=0; cards.forEach(card=>{const supportsTax=(card.dataset.taxModes||'').split(',').includes(tax);const show=card.dataset.paper===format&&(!tax||supportsTax)&&(!gst||card.dataset.gst===gst)&&(!style||card.dataset.style===style);card.classList.toggle('hidden',!show);if(show)visible++;const checked=card.querySelector('input').checked;card.querySelector('[data-selected-badge]').classList.toggle('hidden',!checked)});let key=selectedTemplate();const selectedCard=cards.find(card=>card.querySelector('input').value===key);if(!formats[key]||!selectedCard||selectedCard.classList.contains('hidden')){const first=cards.find(card=>!card.classList.contains('hidden'));if(first){first.querySelector('input').checked=true;key=first.querySelector('input').value;}}cards.forEach(card=>card.querySelector('[data-selected-badge]').classList.toggle('hidden',!card.querySelector('input').checked));const orientations=formats[key]?.orientations||[];orientation.classList.toggle('hidden',orientations.length===0);const select=orientation.querySelector('select');[...select.options].forEach(option=>option.hidden=!orientations.includes(option.value));if(!orientations.includes(select.value))select.value='portrait';count.textContent=`${visible} design${visible===1?'':'s'} available`;if(preview){const data=new FormData(form);const query=new URLSearchParams();data.forEach((value,key)=>{if(key!=='_token'&&key!=='_method')query.append(key,value)});preview.src=`${preview.dataset.previewUrl}?${query}`;}};form.addEventListener('change',refresh);form.addEventListener('input',event=>{if(['brand_color','payment_qr_uri'].includes(event.target.name))refresh()});refresh();})();
    </script>
